import {actionPose,articulated,signature,ACTION_STYLES} from './character-actions.js';
import {motion} from './animation-profiles.js';
import {HEROES,CLIPS} from './data.js';
import {evaluatePose,frameMetadata} from './pose.js';
import {DESIGNS,CATALOGUE_SOURCES} from './catalogue.js';
import {ENERGY_PROFILES} from './combat.js';
import {characterImage,characterManifest,loadCharacterArt} from './character-art.js';
export {loadCharacterArt};
function canvas(w=128,h=128){const c=document.createElement('canvas');c.width=w;c.height=h;return c;}
const rasterCache=new Map();
function hardAlpha(c){const ctx=c.getContext('2d'),image=ctx.getImageData(0,0,c.width,c.height);for(let i=3;i<image.data.length;i+=4)image.data[i]=image.data[i]>=110?255:0;ctx.putImageData(image,0,0);}
function prop(ctx,kind,p,frame){const x=Math.round(p.handR.x),y=Math.round(p.handR.y);ctx.save();ctx.imageSmoothingEnabled=false;ctx.translate(x,y);if(kind==='chop'||kind==='mine'){ctx.rotate((frame<3?-1.1:.7));ctx.fillStyle='#352c33';ctx.fillRect(-3,-27,6,47);ctx.fillStyle='#9d704d';ctx.fillRect(-2,-26,3,45);ctx.fillStyle='#d1b07d';ctx.fillRect(-1,-25,1,42);if(kind==='chop'){ctx.fillStyle='#344151';ctx.fillRect(-1,-29,20,16);ctx.fillStyle='#a9c9d7';ctx.fillRect(2,-27,15,12);ctx.fillStyle='#e4edf0';ctx.fillRect(14,-26,3,10);}else{ctx.fillStyle='#344151';ctx.fillRect(-19,-27,38,6);ctx.fillStyle='#c8dce4';ctx.fillRect(-18,-26,36,3);ctx.fillRect(16,-24,3,8);}}
 if(kind==='water'){ctx.fillStyle='#263e53';ctx.fillRect(-8,-6,19,16);ctx.fillStyle='#74b5bf';ctx.fillRect(-6,-4,15,12);ctx.fillStyle='#aedee1';ctx.fillRect(-5,-3,3,10);ctx.fillStyle='#72afbd';ctx.fillRect(9,-3,13,4);ctx.fillRect(19,-7,5,6);for(let i=0;i<4;i++){ctx.fillStyle='#b0e7f1';ctx.fillRect(23+i*3,1+i*4,2,3);}}
 ctx.restore();}
function rasterHero(hero,clip,frame,direction,gear){const key=`${hero}/${clip}/${frame}/${direction}/${gear}`;if(rasterCache.has(key))return rasterCache.get(key);const p=evaluatePose(clip,frame,direction,gear),kind=p.kind,active=['melee','blue','red','purple','unseal'].includes(kind),combat=active&&(kind!=='unseal'||frame>2),source=characterImage(hero,direction,gear,combat);const out=canvas(),c=out.getContext('2d');if(!source)return out;c.imageSmoothingEnabled=false;c.save();if(direction==='west'){c.translate(128,0);c.scale(-1,1);}const m=motion(hero),phase=p.phase*Math.PI*2;const tilt=kind==='dash'?m.attack:kind==='hurt'?-m.attack:active?Math.sin(phase)*m.attack:Math.sin(phase)*m.sway;const bob=Math.round(p.root.y*m.bounce),shift=Math.round(p.root.x*.6);if(kind==='idle'||kind==='guard')p.sy=1+Math.sin(phase)*m.breath;
 if(kind==='defeat'){const f=Math.min(1,p.phase*1.7);c.translate(64-5*f,116-32*f);c.rotate(f*Math.PI/2);c.translate(-64,-116+40*f);}else{c.translate(64+shift,116+bob);c.rotate(tilt*Math.PI/180);c.scale(p.sx,kind==='sit'?.83:p.sy);c.translate(-64,-116);}
 const action=actionPose(hero,kind,p.phase);if(['melee','blue','red','purple','dash'].includes(kind)){action.x*=1.9;action.lean*=1.2;action.left*=1.15;action.right*=1.15;action.y-=Math.round(Math.sin(p.phase*Math.PI)*5);}if(kind==='walk'){action.leg*=1.7;action.left*=1.5;action.right*=1.5;action.y*=1.5;}articulated(c,source,action);
 signature(c,hero,kind,p.phase);if(['melee','blue','red','purple'].includes(kind)){c.save();c.globalAlpha=.65*Math.sin(p.phase*Math.PI);c.fillStyle=hero==='yuji'?'#fa5e7c':hero==='megumi'?'#385768':hero==='nobara'?'#e9b990':hero==='maki'?'#a9dcaf':hero==='yuta'?'#d6c6ff':'#8adfff';for(let i=0;i<9;i++){const angle=i*.45+p.phase*3;c.fillRect(Math.round(64+Math.cos(angle)*(32+i*2)),Math.round(75+Math.sin(angle)*(20+i)),4,3);}c.restore();}
 if(hero==='gojo'&&combat&&p.eye!=='eyes'){c.fillStyle='#171728';c.fillRect(49,35,33,8);c.fillRect(47,37,37,4);c.fillStyle='#3d354e';c.fillRect(51,36,29,1);}
 if(['chop','mine','water'].includes(kind))prop(c,kind,p,frame);
 if(kind==='sit'&&frame>=3){c.fillStyle='#b5947b';c.fillRect(66,61,16,8);c.fillStyle='#f4ddd0';c.fillRect(68,60,12,7);c.fillStyle='#fff0d9';c.fillRect(70,60,7,2);}
 if(kind==='wave'){c.fillStyle='#ee97b4';c.fillRect(92,26,4,4);c.fillRect(98,26,4,4);c.fillRect(94,30,6,4);c.fillRect(96,34,2,2);}
 c.restore();hardAlpha(out);if(rasterCache.size>512)rasterCache.delete(rasterCache.keys().next().value);rasterCache.set(key,out);return out;}
export function drawHero(ctx,hero='gojo',clip=0,frame=0,direction='south',gear='blindfold',debug=false){const id=typeof hero==='string'?hero:hero.id;ctx.save();ctx.imageSmoothingEnabled=false;ctx.drawImage(rasterHero(id,clip,frame,direction,gear),0,0,128,128);if(debug){const p=evaluatePose(clip,frame,direction,gear);ctx.strokeStyle='#ffab8e';ctx.lineWidth=1;ctx.strokeRect(43,29,42,87);ctx.fillStyle='#a9f4ff';for(const a of [p.handL,p.handR])ctx.fillRect(Math.round(a.x)-2,Math.round(a.y)-2,4,4);ctx.fillStyle='#ff6c8f';ctx.fillRect(59,115,11,2);ctx.fillRect(63,111,2,10);}ctx.restore();}
export function heroCanvas(id,clip=0,frame=0,direction='south',gear='blindfold'){const c=canvas();drawHero(c.getContext('2d'),id,clip,frame,direction,gear);return c;}
export function portrait(id){const c=canvas(),ctx=c.getContext('2d'),source=characterImage(id,'south',id==='gojo'?'eyes':'blindfold');ctx.imageSmoothingEnabled=false;if(source)ctx.drawImage(source,25,0,78,68,0,0,128,128);return c.toDataURL();}
export const ENEMY_CLIPS=['idle','walk','telegraph','attack','hurt','defeat','recovery'];
export function drawEnemyAnimation(ctx,e,kind='idle',frame=0){const out=canvas(),c=out.getContext('2d'),source=characterImage(e.id,'south','blindfold',kind==='attack');if(!source)return;const m=motion(e.id),phase=frame/8*Math.PI*2;c.imageSmoothingEnabled=false;c.save();c.translate(64,116);if(kind==='walk'){c.translate(Math.round(Math.sin(phase)*m.sway),-Math.round(Math.abs(Math.sin(phase))*m.bounce));c.rotate(Math.sin(phase)*m.stride*.25+Math.cos(phase+.3)*.035);c.translate(Math.cos(phase)*2,0);}if(kind==='idle'||kind==='recovery')c.scale(1,1+Math.sin(phase)*m.breath);if(kind==='telegraph'){c.scale(1.04,1-Math.sin(frame/8*Math.PI)*.07);c.translate(Math.round(Math.sin(phase*2)*2),0);}if(kind==='attack'){c.translate(Math.sin(frame/8*Math.PI)*m.attack,0);c.rotate(-Math.sin(phase)*m.stride);}if(kind==='hurt'){c.translate(-Math.sin(frame/8*Math.PI)*5,0);c.rotate(-.08*Math.sin((frame+1)/9*Math.PI));}if(kind==='defeat'){const f=Math.min(1,frame/5);c.translate(-5*f,-32*f);c.rotate(f*Math.PI/2);c.translate(0,40*f);}c.translate(-64,-116);if(kind==='walk'&&e.id!=='fly'){c.drawImage(source,0,0,128,94,0,0,128,94);for(const [side,start,hip]of [[-1,0,53],[1,64,75]]){c.save();c.translate(hip,94);c.rotate(Math.sin(phase)*m.stride*side);c.translate(-hip,-94);c.drawImage(source,start,94,64,34,start,94,64,34);c.restore();}}else articulated(c,source,actionPose(e.id,kind==='attack'?'melee':kind==='telegraph'?'blue':kind,frame/8));signature(c,e.id,kind,frame/8);c.restore();hardAlpha(out);ctx.save();ctx.imageSmoothingEnabled=false;ctx.drawImage(out,0,0,128,128);ctx.restore();}
export function drawEnemy(ctx,e,t=0){drawEnemyAnimation(ctx,e,'idle',Math.floor(t*12)%8);}
export function createAtlas(hero,gear='blindfold',direction='south',supplement=false){if(!characterManifest())throw new Error('Load the character artwork before baking');const clips=supplement?CLIPS.slice(18):CLIPS.slice(0,18),out=canvas(1024,clips.length*128),c=out.getContext('2d');c.imageSmoothingEnabled=false;for(let r=0;r<clips.length;r++)for(let f=0;f<clips[r].frames;f++){c.save();c.translate(f*128,r*128);drawHero(c,hero,clips[r].row,f,direction,gear);c.restore();}return out;}
export function atlasMetadata(hero,gear,direction,supplement=false){return {version:3,style:'poster-chibi-pixel',nativeGrid:128,sourceStyle:'battle-poster',actionStyle:ACTION_STYLES[hero],motion:motion(hero),reference:'art/battle-poster.webp',artwork:`art/characters/${hero}-${direction==='west'?'side':direction}.png`,hero,gear,direction,design:DESIGNS[hero],sources:CATALOGUE_SOURCES,cell:{w:128,h:128},anchor:{x:64,y:116},pixelsPerUnit:96,animations:(supplement?CLIPS.slice(18):CLIPS.slice(0,18)).map(c=>({...c,duration:c.frames/c.fps,framesData:Array.from({length:c.frames},(_,f)=>frameMetadata(c.row,f,direction,gear))}))};}
export function createEnemyAtlas(e){const out=canvas(1024,896),c=out.getContext('2d');for(let r=0;r<7;r++)for(let f=0;f<8;f++){c.save();c.translate(f*128,r*128);drawEnemyAnimation(c,e,ENEMY_CLIPS[r],f);c.restore();}return out;}
export function enemyMetadata(e){return {version:3,style:'poster-chibi-pixel',nativeGrid:128,reference:'art/battle-poster.webp',character:e.id,actionStyle:ACTION_STYLES[e.id],motion:motion(e.id),baseCombat:{hp:e.hp,damage:e.damage,speed:e.speed,cursedEnergy:ENERGY_PROFILES[e.id]},design:DESIGNS[e.id],sources:CATALOGUE_SOURCES,cell:{w:128,h:128},anchor:{x:64,y:116},animations:ENEMY_CLIPS.map((id,row)=>({id,frames:8,fps:12,duration:8/12,framesData:Array.from({length:8},(_,f)=>({frame:f,rect:{x:f*128,y:row*128,w:128,h:128},duration:1/12,active:id==='attack'&&f===3}))}))};}
export function companionCanvas(id,frame=0,kind='idle'){const c=canvas();drawEnemyAnimation(c.getContext('2d'),{id},kind,frame);return c;}
